// 1. Obtener respuestas consolidadas
const respuestas = $input.item.json;

// 2. Intentar obtener las keywords desde el nodo de preguntas específico según el lenguaje
let datosPreguntas = {};

try {
  const lenguaje = String(respuestas['Lenguaje de Programacion'] || '').toLowerCase();

  if (lenguaje.includes('python')) {
    datosPreguntas = $('Questions_Python').first().json;
  } else if (lenguaje.includes('javascript')) {
    datosPreguntas = $('Questions_JavaScript').first().json;
  } else if (lenguaje.includes('java')) {
    datosPreguntas = $('Questions_Java').first().json;
  } else if (lenguaje.includes('c++')) {
    datosPreguntas = $('Questions_C++').first().json;
  } else if (lenguaje.includes('c#')) {
    datosPreguntas = $('Questions_C#').first().json;
  } else {
    datosPreguntas = $('Switch2').all()[0]?.json || {};
  }
} catch (e) {
  datosPreguntas = {};
}

let aciertos = 0;
let detalles = [];

for (let i = 1; i <= 5; i++) {
  // Buscar campo respuesta_i o Respuesta_i
  const claveRespuesta = Object.keys(respuestas).find(k => k.toLowerCase() === `respuesta_${i}`);
  const userRespRaw = claveRespuesta ? respuestas[claveRespuesta] : '';

  // Normalizar texto del usuario (minúsculas y sin acentos)
  const userResp = String(userRespRaw || '')
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "");

  // Obtener la lista de keywords
  const rawKw = datosPreguntas[`keywords_${i}`] || '';
  const keywordsList = String(rawKw)
    .split(',')
    .map(k => k.trim().toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, ""))
    .filter(k => k.length > 0);

  // Evaluar coincidencia
  const coincide = keywordsList.some(kw => userResp.includes(kw));
  if (coincide) aciertos++;

  detalles.push({
    pregunta: i,
    respuesta_recibida: userRespRaw,
    keywords_buscadas: keywordsList,
    es_correcta: coincide
  });
}

return {
  json: {
    ...respuestas,
    total_correctas: aciertos,
    total_preguntas: 5,
    detalles_evaluacion: detalles
  }
};

